import{_ as e,H as a,f as l,i as s}from"./chunks/framework.DLd0CbzH.js";const p=JSON.parse('{"title":"Настройки пространства","description":"Управление ставкой мастера, наценкой, накладными расходами и локальными параметрами текущего рабочего пространства.","frontmatter":{"title":"Настройки пространства","description":"Управление ставкой мастера, наценкой, накладными расходами и локальными параметрами текущего рабочего пространства.","order":13},"headers":[],"relativePath":"ru/docs/spaces/production/space-settings.md","filePath":"ru/docs/spaces/production/space-settings.md"}'),r={name:"ru/docs/spaces/production/space-settings.md"};function o(n,t,i,d,c,g){return a(),l("div",null,[...t[0]||(t[0]=[s('<div class="warning custom-block"><p class="custom-block-title">📌 Документация находится в разработке</p><p><strong>Уважаемые пользователи!</strong></p><p>Поскольку ОмниКрафт ЕРП сейчас находится в стадии активной бета-версии, регулярно дорабатывается и расширяется, справочные материалы также обновляются постепенно.</p><p>На данный момент воспринимайте документацию как ориентировочную — она является неполной, может временно не содержать описание некоторых функций или содержать неточности.</p></div><h1 id="⚙️-настроики-пространства-экономическии-фундамент" tabindex="-1">⚙️ Настройки пространства: Экономический фундамент <a class="header-anchor" href="#⚙️-настроики-пространства-экономическии-фундамент" aria-label="Permalink to &quot;⚙️ Настройки пространства: Экономический фундамент&quot;">​</a></h1><p>Вкладка <strong>«Настройки пространства»</strong> — это пульт управления рентабельностью вашего бизнеса. Здесь задаются глобальные нормативы, которые автоматически подставляются в Калькулятор себестоимости, влияют на формирование розничных цен и честно распределяют косвенные затраты на каждое изделие.</p><p>Эти параметры уникальны для каждого рабочего пространства. Если вы ведете несколько брендов или направлений в PRO-режиме, у каждого из них будет своя ставка, своя наценка и свои статьи накладных расходов.</p><hr><h2 id="⏱️-системная-ставка-мастера-₽-час" tabindex="-1">⏱️ Системная ставка мастера (₽/час) <a class="header-anchor" href="#⏱️-системная-ставка-мастера-₽-час" aria-label="Permalink to &quot;⏱️ Системная ставка мастера (₽/час)&quot;">​</a></h2><p>Это стоимость вашего рабочего времени. Программа использует эту цифру для автоматического расчета трудозатрат при создании или редактировании рецепта изделия.</p><ul><li><strong>Как работает:</strong> Если на пошив сумки заложено <code>2.5</code> часа нормы, а ставка равна <code>800 ₽/час</code>, программа автоматически добавит <code>2 000 ₽</code> в себестоимость изделия в статье «Стоимость работы».</li><li><strong>Зачем менять:</strong> Ставка должна отражать вашу реальную квалификацию, скорость и рыночные расценки. Регулярно повышайте её по мере роста навыков, чтобы цена изделий не отставала от вашей ценности как мастера.</li><li><strong>Где применяется:</strong> Во всех новых расчетах Калькулятора и при планировании производственных партий.</li></ul><hr><h2 id="📈-глобальная-наценка" tabindex="-1">📈 Глобальная наценка (%) <a class="header-anchor" href="#📈-глобальная-наценка" aria-label="Permalink to &quot;📈 Глобальная наценка (%)&quot;">​</a></h2><p>Базовый процент прибыли, который программа автоматически накидывает на <strong>полную себестоимость</strong> изделия (материалы + работа + накладные расходы) при формировании розничной цены.</p><p>$$\\text{Розничная цена} = \\text{Полная себестоимость} \\times \\left(1 + \\frac{\\text{Наценка}}{100}\\right)$$</p><ul><li><strong>Гибкость:</strong> Это значение подставляется в Калькулятор по умолчанию, но вы всегда можете скорректировать его вручную для конкретного товара (например, для акционной позиции или, наоборот, для лимитированной коллекции).</li><li><strong>Бизнес-смысл:</strong> Наценка — это ваш запас прочности. Она должна покрывать не только прибыль, но и риски брака, сезонные спады и стоимость привлечения клиента.</li></ul><hr><h2 id="📦-накладные-расходы-косвенные-затраты" tabindex="-1">📦 Накладные расходы (Косвенные затраты) <a class="header-anchor" href="#📦-накладные-расходы-косвенные-затраты" aria-label="Permalink to &quot;📦 Накладные расходы (Косвенные затраты)&quot;">​</a></h2><p>Бизнес — это не только кожа, фурнитура и нитки. Аренда мастерской, электричество, реклама, упаковка, хостинг сайта, комиссии маркетплейсов и амортизация инструментов тоже стоят денег. В ОмниКрафт ЕРП вы можете создать неограниченное количество статей накладных расходов, которые будут <strong>автоматически распределяться на каждое изделие</strong>.</p><h3 id="типы-нормативов-распределения" tabindex="-1">Типы нормативов распределения <a class="header-anchor" href="#типы-нормативов-распределения" aria-label="Permalink to &quot;Типы нормативов распределения&quot;">​</a></h3><p>При добавлении статьи расхода вы выбираете один из двух методов расчета:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Тип норматива</th><th style="text-align:left;">Как рассчитывается</th><th style="text-align:left;">Для чего лучше подходит</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>📊 Процент (%)</strong></td><td style="text-align:left;">Доля от стоимости материалов или базовой себестоимости</td><td style="text-align:left;">Комиссии площадок, логистика, упаковка, зависящая от цены товара.</td></tr><tr><td style="text-align:left;"><strong>🏷️ Фиксированная сумма</strong></td><td style="text-align:left;">Жесткая сумма, добавляемая к каждой единице изделия</td><td style="text-align:left;">Аренда (в пересчете на плановый объем), бирки, гарантийные талоны, фиксированные сборы.</td></tr></tbody></table><h3 id="управление-статьями-расходов" tabindex="-1">Управление статьями расходов <a class="header-anchor" href="#управление-статьями-расходов" aria-label="Permalink to &quot;Управление статьями расходов&quot;">​</a></h3><ul><li><strong>Добавление:</strong> Введите название статьи, выберите тип норматива и укажите глобальное значение. Нажмите «Добавить» — статья мгновенно появится в списке.</li><li><strong>Редактирование:</strong> Вы можете изменить значение или тип норматива в любой момент. Обновленные параметры применятся к следующим расчетам.</li><li><strong>Удаление:</strong> Если статья больше не актуальна, её можно удалить.</li></ul><div class="warning custom-block"><p class="custom-block-title">Важно</p><p>Удаление или изменение статьи накладных расходов <strong>не пересчитывает исторические продажи и старые рецепты</strong>. Статья просто перестанет учитываться в новых расчетах глобальной себестоимости. Это гарантирует, что ваша прошлая финансовая отчетность останется неизменной и юридически корректной.</p></div><hr><h2 id="🗓️-отображение-выбора-даты-календарь" tabindex="-1">🗓️ Отображение выбора даты (Календарь) <a class="header-anchor" href="#🗓️-отображение-выбора-даты-календарь" aria-label="Permalink to &quot;🗓️ Отображение выбора даты (Календарь)&quot;">​</a></h2><p>Небольшая, но полезная интерфейсная настройка. По умолчанию поля ввода дат в программе скрыты для экономии места и ускорения работы: система автоматически подставляет текущую дату («сегодня»).</p><p>Если вам часто требуется проводить операции «задним числом», планировать будущие списания или фиксировать точные даты отгрузок, разверните этот спойлер и включите визуальный календарь. Настройка сохраняется локально и не влияет на расчеты.</p><hr><h2 id="💾-сохранение-и-точность-данных" tabindex="-1">💾 Сохранение и точность данных <a class="header-anchor" href="#💾-сохранение-и-точность-данных" aria-label="Permalink to &quot;💾 Сохранение и точность данных&quot;">​</a></h2><p>После внесения изменений нажмите кнопку <strong>«Сохранить настройки»</strong>. Программа проверит корректность введенных чисел (все поля должны быть заполнены) и запишет их в базу текущего пространства.</p><div class="info custom-block"><p class="custom-block-title">Техническая точность</p><p>Все финансовые нормативы (ставка, наценка, значения накладных) хранятся в базе данных в <strong>высокоточном целочисленном формате</strong> (масштаб 10 000). Это полностью исключает ошибки округления, «потерю копеек» и накопление погрешностей при длительной эксплуатации программы, даже при работе с дробными часами или сложными процентами.</p></div><hr><h2 id="🧠-как-настроики-влияют-на-экономику-мастерскои" tabindex="-1">🧠 Как настройки влияют на экономику мастерской? <a class="header-anchor" href="#🧠-как-настроики-влияют-на-экономику-мастерскои" aria-label="Permalink to &quot;🧠 Как настройки влияют на экономику мастерской?&quot;">​</a></h2><p>Все три параметра работают в связке внутри <strong>Калькулятора</strong> и напрямую формируют вашу прибыль:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Параметр</th><th style="text-align:left;">На что влияет</th><th style="text-align:left;">Бизнес-последствие изменения</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Ставка мастера</strong></td><td style="text-align:left;">Себестоимость работы</td><td style="text-align:left;">Повышение ставки увеличивает «замороженные» деньги в готовых изделиях и честно показывает стоимость вашего времени.</td></tr><tr><td style="text-align:left;"><strong>Накладные расходы</strong></td><td style="text-align:left;">Полная себестоимость</td><td style="text-align:left;">Делает цену реальной. Без них прибыль кажется выше, чем есть на самом деле, что ведет к кассовым разрывам.</td></tr><tr><td style="text-align:left;"><strong>Наценка</strong></td><td style="text-align:left;">Розничная цена и маржа</td><td style="text-align:left;">Прямо влияет на выручку и средний чек. Слишком высокая наценка может снизить конверсию, слишком низкая — обесценить труд.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Совет по управлению</p><p>Не меняйте глобальные настройки слишком часто. Резкие скачки ставки или накладных расходов исказят сравнительную аналитику за прошлые периоды. Лучше корректировать их <strong>раз в квартал</strong> или при существенном изменении бизнес-условий (переезд мастерской, рост тарифов на логистику, выход на новый уровень мастерства).</p></div>',35)])])}const u=e(r,[["render",o]]);export{p as __pageData,u as default};
